/**
 * 正经、搞笑、涩涩三种基调统一使用无预设的 generateRaw。
 * 基调只改变提示词内容，不改变生成通道，避免当前酒馆预设把结构化任务带回剧情续写。
 * 所有路径都额外加入结构化输出约束，避免文风提示破坏 JSON。
 */
async function requestTechniques(prompt, config) {
    const engineRole = config.道途身份 === '非修士'
        ? '你是一个黑暗修仙世界中的凡人技艺与人生专长设计引擎。'
        : '你是一个修仙世界功法设计引擎。';
    const systemPrompt = `${engineRole}你的唯一任务是按照用户要求生成结构化的分支 JSON 数据。${JSON输出约束}`;
    console.info(`[功法分支] ${config.本源基调}基调：使用无预设 generateRaw 生成结构化候选`);
    return generateRaw({
        user_input: prompt,
        should_silence: true,
        ordered_prompts: [{ role: 'system', content: systemPrompt }, 'user_input'],
    });
}
function parseTechniquesResult(result) {
    const text = typeof result === 'string' ? result : result.content || JSON.stringify(result);
    console.info('[功法分支] AI 返回原始文本（前300字）:', text.slice(0, 300));
    const parsed = extractJSON(text);
    const obj = parsed;
    let techniques;
    if (Array.isArray(obj)) {
        techniques = obj;
    }
    else if (obj && typeof obj === 'object') {
        techniques = obj.techniques ?? obj.功法 ?? obj.data ?? obj;
        if (!Array.isArray(techniques)) {
            techniques = Object.values(obj).find(Array.isArray) ?? techniques;
        }
    }
    else {
        techniques = obj;
    }
    if (!Array.isArray(techniques)) {
        throw new Error('AI 返回的分支数据不是数组');
    }
    return techniques;
}
// ── 校验 ──────────────────────────────────────────────
function validateBranch(techniques, triggerName, targetLevel, existingNames) {
    const 合法 = [];
    for (const raw of techniques) {
        const t = 映射字段名(raw);
        if (!t.名称 || typeof t.名称 !== 'string' || !t.名称.trim())
            continue;
        if (existingNames.has(t.名称)) {
            console.info(`[功法分支] 跳过重复名称: ${t.名称}`);
            continue;
        }
        existingNames.add(t.名称);
        const parsed = AI功法条目Schema.safeParse(t);
        if (!parsed.success) {
            console.warn(`[功法分支] 跳过无法修正的条目: ${JSON.stringify(t)}`, parsed.error.issues);
            continue;
        }
        const 功 = parsed.data;
        // 强制层级为目标层级
        if (功.层级 !== targetLevel) {
            console.info(`[功法分支] 调整层级: ${功.名称} 从 ${功.层级} 调整为 ${targetLevel}`);
            功.层级 = targetLevel;
        }
        // 进阶分支一律未学习；非修士根基会在上层映射为已掌握。
        功.已学习 = false;
        合法.push(功);
    }
    // 确保至少有 1 个功法以触发功法为前置
    const 有触发前置 = 合法.some(t => t.前置功法 === triggerName);
    if (!有触发前置 && 合法.length > 0) {
        合法[0].前置功法 = triggerName;
        console.info(`[功法分支] 自动设置"${合法[0].名称}"的前置功法为"${triggerName}"`);
    }
    return 合法;
}
// ── 增量生成主函数 ─────────────────────────────────────
/**
 * 为指定功法生成下一级分支（AI 调用）。
 * @returns 合法功法列表，或 null（生成失败/无合法结果）
 */
export async function generateBranch(statData, triggerName, triggerLevel, config) {
    const 目标层级 = triggerLevel + 1;
    const existingNames = new Set([
        ...功法列表.map(g => g.名称),
        ...Object.keys(statData.功法),
        ...Object.keys(statData.初始功法 ?? {}),
    ]);
    const prompt = buildBranchPrompt(statData, triggerName, triggerLevel, existingNames, config);
    if (!prompt)
        return null;
    const 分支类型 = config.道途身份 === '非修士' ? '技艺' : '功法';
    console.info(`[功法分支] 开始为"${triggerName}"生成第${目标层级}阶${分支类型}分支`);
    try {
        const result = await requestTechniques(prompt, config);
        let techniques;
        try {
            techniques = parseTechniquesResult(result);
        }
        catch (err) {
            console.error('[功法分支] 解析 AI 返回失败:', err);
            return null;
        }
        const 合法功法 = validateBranch(techniques, triggerName, 目标层级, existingNames);
        if (合法功法.length === 0) {
            console.warn('[功法分支] AI 生成的功法全部无效');
            return null;
        }
        console.info(`[功法分支] 成功生成 ${合法功法.length} 个第${目标层级}阶${分支类型}分支`);
        return 合法功法;
    }
    catch (err) {
        console.error('[功法分支] 生成失败:', err);
        return null;
    }
}
/** 根据多项已学习功法生成一项新的归元功法；只返回校验后的单条结果，不修改变量。 */
export async function generateFusion(statData, selected, targetLevel, config) {
    const existingNames = new Set([
        ...功法列表.map(g => g.名称),
        ...Object.keys(statData.功法),
        ...Object.keys(statData.初始功法 ?? {}),
    ]);
    const prompt = buildFusionPrompt(statData, selected, targetLevel, config, existingNames);
    try {
        const result = await requestTechniques(prompt, config);
        const candidates = parseTechniquesResult(result);
        for (const raw of candidates) {
            const mapped = 映射字段名(raw);
            if (!mapped || typeof mapped.名称 !== 'string' || !mapped.名称.trim() || existingNames.has(mapped.名称))
                continue;
            const parsed = AI功法条目Schema.safeParse(mapped);
            if (!parsed.success)
                continue;
            const fused = parsed.data;
            fused.层级 = targetLevel;
            fused.前置功法 = '';
            fused.已学习 = true;
            fused.消耗灵悟 = 层级消耗[targetLevel] ?? Math.max(5, targetLevel * 10);
            if (fused.类型 === '主动')
                fused.属性加成 = '';
            return fused;
        }
        console.warn('[功法归元] AI 未返回可用的融合功法');
        return null;
    }
    catch (err) {
        console.error('[功法归元] 生成融合功法失败:', err);
        return null;
    }
}
/** 修士开场功法树为空时，仅依据灵魂本源与修炼流派生成未学习的一级根功法。 */
export async function generateCultivatorRoots(statData, config) {
    const existingNames = new Set([
        ...功法列表.map(g => g.名称),
        ...Object.keys(statData.功法),
        ...Object.keys(statData.初始功法 ?? {}),
    ]);
    console.info('[功法分支] 修士功法树为空：仅按灵魂本源与修炼流派生成一级根功法');
    try {
        const 候选 = [];
        // 模型偶尔少给条目；最多补生成一次，合并后截取 3-5 个。
        for (let attempt = 1; attempt <= 2 && 候选.length < 3; attempt++) {
            const prompt = buildCultivatorRootPrompt(statData, config);
            // 三种基调统一使用隔离上下文，避免预设、聊天记录或世界书带入额外功法。
            const result = await requestTechniques(prompt, config);
            let techniques;
            try {
                techniques = parseTechniquesResult(result);
            }
            catch (err) {
                console.error(`[功法分支] 第 ${attempt} 次解析修士根功法失败:`, err);
                continue;
            }
            const 本轮合法 = validateBranch(techniques, '', 1, existingNames).map(technique => ({
                ...technique,
                层级: 1,
                前置功法: '',
                已学习: false,
            }));
            候选.push(...本轮合法);
            console.info(`[功法分支] 第 ${attempt} 次取得 ${本轮合法.length} 个有效修士根功法，累计 ${候选.length} 个`);
        }
        if (候选.length < 3) {
            console.warn(`[功法分支] 修士初始功法树至少需要 3 个有效根功法，实际仅 ${候选.length} 个`);
            return null;
        }
        const 根功法 = 候选.slice(0, 5);
        console.info(`[功法分支] 成功生成 ${根功法.length} 个仅由本源与修炼流派推导的修士根功法`);
        return 根功法;
    }
    catch (err) {
        console.error('[功法分支] 生成修士根功法失败:', err);
        return null;
    }
}
/** 当非修士尚无功法树根节点时，依据灵魂本源生成已掌握的凡俗根基。 */
export async function generateNonCultivatorRoots(statData, config) {
    const existingNames = new Set([
        ...功法列表.map(g => g.名称),
        ...Object.keys(statData.功法),
        ...Object.keys(statData.初始功法 ?? {}),
    ]);
    console.info('[功法分支] 非修士功法树为空：开始生成凡俗根基');
    try {
        const 候选 = [];
        // 模型偶尔少给条目；最多补生成一次，合并后截取 5-6 个，确保成功时一定有完整的初始小树。
        for (let attempt = 1; attempt <= 2 && 候选.length < 5; attempt++) {
            const prompt = buildNonCultivatorRootPrompt(statData, existingNames, config);
            const result = await requestTechniques(prompt, config);
            let techniques;
            try {
                techniques = parseTechniquesResult(result);
            }
            catch (err) {
                console.error(`[功法分支] 第 ${attempt} 次解析非修士根基失败:`, err);
                continue;
            }
            const 本轮合法 = validateBranch(techniques, '', 1, existingNames);
            候选.push(...本轮合法);
            console.info(`[功法分支] 第 ${attempt} 次取得 ${本轮合法.length} 个有效凡俗技艺候选，累计 ${候选.length} 个`);
        }
        if (候选.length < 5) {
            console.warn(`[功法分支] 非修士初始树至少需要 5 个有效候选，实际仅 ${候选.length} 个`);
            return null;
        }
        const 初始树 = 组织非修士初始树(候选.slice(0, 6));
        const 已学习数 = 初始树.filter(technique => technique.已学习).length;
        console.info(`[功法分支] 成功生成 ${初始树.length} 个非修士凡俗技艺（已掌握 ${已学习数}，待领悟 ${初始树.length - 已学习数}）`);
        return 初始树;
    }
    catch (err) {
        console.error('[功法分支] 生成非修士根基失败:', err);
        return null;
    }
}
/**
 * 将 5-6 个候选技艺整理成开局即可使用的小型树：
 * - 前半 2-3 个是已掌握的一级根基；
 * - 其余是挂在根基下的未学习二阶分支。
 *
 * 这样既保证开局有能力可用，也避免所有根节点都成为“无后续末端”，导致一次进阶连续请求多次。
 */
export function 组织非修士初始树(候选) {
    const 限定候选 = 候选.slice(0, 6);
    if (限定候选.length < 5) {
        throw new Error(`非修士初始树至少需要 5 个候选，当前仅 ${限定候选.length} 个`);
    }
    const 根基数量 = Math.floor(限定候选.length / 2);
    const 根基 = 限定候选.slice(0, 根基数量).map(technique => ({
        ...technique,
        层级: 1,
        前置功法: '',
        已学习: true,
        消耗灵悟: 0,
    }));
    const 分支 = 限定候选.slice(根基数量).map((technique, index) => ({
        ...technique,
        层级: 2,
        前置功法: 根基[index % 根基.length].名称,
        已学习: false,
        消耗灵悟: 层级消耗[2],
    }));
    return [...根基, ...分支];
}
// ── 将新功法写入变量 ────────────────────────────────────
/**
 * 把 AI 生成的新功法写入 stat_data.功法 树。
 * 修士功法名包含流派关键字时灵悟消耗打五折；非修士不套用流派折扣。
 */
export function writeBranchToData(statData, techniques) {
    const 流派关键字 = 查流派(statData.主角.修炼流派)?.关键字 ?? '';
    const 非修士 = statData.主角.境界 === '凡人' && statData.主角.灵根 === '无';
    for (const t of techniques) {
        const 名称含流派 = !非修士 && 流派关键字 && t.名称.includes(流派关键字);
        const 流派折扣 = 名称含流派 ? 0.5 : 1;
        statData.功法[t.名称] = {
            类型: t.类型,
            层级: t.层级,
            前置功法: t.前置功法,
            效果: t.效果,
            属性加成: t.类型 === '被动' ? t.属性加成 : '',
            已学习: t.已学习,
            消耗灵悟: t.已学习 && t.前置功法 === '' ? 0 : Math.max(5, Math.round(层级消耗[t.层级] * 流派折扣)),
            描述: t.描述 ?? '',
        };
    }
    // 功法加成由前端显示层叠加（见 ProtagonistTab 雷达图），不再写入六维变量。
}
